actual_early_constants:
// EARLIEST path constants for the Electron main process.
//
// CONSTRAINTS:
//   - No business-module dependencies (no @shared / @main / business code).
//   - Only node built-ins and `electron` are allowed.
//   - Electron's `app.getPath()` is safe at this layer: it works at module
//     import time, before `app.whenReady()`. Verified by LoggerService which
//     constructs at module load and consumes LOGS_DIR through this file.
//
// CONSUMERS (all main-process bootstrap services):
//   - src/main/core/logger/LoggerService.ts          → uses LOGS_DIR
//   - src/main/data/bootConfig/BootConfigService.ts  → uses BOOT_CONFIG_PATH
//   - src/main/core/paths/pathRegistry.ts            → re-exposes LOGS_DIR as 'app.logs'
//   - src/main/core/preboot/userDataLocation.ts      → uses resolveDevUserDataPath

import os from 'node:os'
import path from 'node:path'

import { app } from 'electron'

// Duplicated from HOME_DIRNAME in @shared/utils/branding: this layer loads
// before app.whenReady() and may not import business modules (see CONSTRAINTS
// above). Change both together.
export const CHERRY_HOME_DIRNAME = '.the-boss'
export const CHERRY_HOME = path.join(os.homedir(), CHERRY_HOME_DIRNAME)
export const BOOT_CONFIG_PATH = path.join(CHERRY_HOME, 'boot-config.json')

const DEFAULT_DEV_USER_DATA_SUFFIX = 'Dev'

// The suffix is concatenated into directory names, so it must stay a single
// path component: separators, drive colons, and control/Windows-forbidden
// characters could normalize the dev directories back onto the packaged ones
// (e.g. `/../CherryStudio`). Trailing dots are rejected separately — Windows
// strips them, aliasing `CherryStudio.` (from suffix `.`) onto the packaged
// `CherryStudio` directory. Anything a filesystem accepts inside a single
// component — spaces, non-ASCII — stays valid.
const FORBIDDEN_DEV_USER_DATA_SUFFIX = /[\\/:*?"<>|]|\p{Cc}/u

/**
 * Dev-instance directory suffix (`CherryStudio` → `CherryStudioDev`),
 * overridable via CS_DEV_USER_DATA_SUFFIX.
 *
 * Blank values fall back to the default; a value that is not a single path
 * component aborts startup instead, because falling back would silently merge
 * a profile meant to be isolated into the shared `Dev` one. Throwing is also
 * the only way to report this: @logger is unavailable here, since
 * LoggerService consumes LOGS_DIR from this file.
 */
function resolveDevUserDataSuffix(): string {
  const configured = process.env.CS_DEV_USER_DATA_SUFFIX?.trim()
  if (!configured) return DEFAULT_DEV_USER_DATA_SUFFIX
  if (FORBIDDEN_DEV_USER_DATA_SUFFIX.test(configured) || configured.endsWith('.')) {
    throw new Error(
      `CS_DEV_USER_DATA_SUFFIX ${JSON.stringify(configured)} must be a single path component ` +
        '(no path separator, drive colon, Windows-reserved character or trailing dot).'
    )
  }
  return configured
}

/**
 * Dev-instance userData directory (`…/CherryStudio` → `…/CherryStudioDev`).
 * Applied by `core/preboot/userDataLocation.ts` and — on Windows and Linux,
 * where logs live inside userData — by the logs diversion below, so both
 * derive from one definition.
 */
export function resolveDevUserDataPath(): string {
  return app.getPath('userData') + resolveDevUserDataSuffix()
}

// Divert dev logs BEFORE the app.getPath('logs') call below caches Electron's
// default. That default never sees the dev userData suffix — on macOS it
// derives from the app *name* (~/Library/Logs/CherryStudio), elsewhere from
// the not-yet-suffixed userData — so without this a dev run would interleave
// its logs with a packaged install's.
if (!app.isPackaged) {
  app.setAppLogsPath(
    process.platform === 'darwin'
      ? app.getPath('logs') + resolveDevUserDataSuffix()
      : path.join(resolveDevUserDataPath(), 'logs')
  )
}

/**
 * Logs directory. Resolves to Electron's platform-standard location:
 *   - macOS:   ~/Library/Logs/<App>/
 *   - Windows: %APPDATA%/<App>/logs
 *   - Linux:   ~/.config/<App>/logs
 * where `<App>` carries the dev suffix in unpackaged runs (see above).
 *
 * Single source of truth — referenced by LoggerService directly and exposed
 * via pathRegistry as the `app.logs` key for `application.getPath()` consumers.
 */
export const LOGS_DIR = app.getPath('logs')

actual_user_data_selection:
import fs from 'node:fs'
import path from 'node:path'

import { app } from 'electron'

import { loggerService } from '@logger'
import { resolveDevUserDataPath } from '@main/core/paths/constants'
import { isLinux, isPortable, isWin } from '@main/core/platform'
import { bootConfigService } from '@main/data/bootConfig'
import { PRODUCT_DIRNAME } from '@shared/utils/branding'

const logger = loggerService.withContext('Preboot')

/** Upstream's userData directory name, detected only to report it, never adopted. */
const LEGACY_UPSTREAM_DIRNAME = 'CherryStudio'

/**
 * "userData" in this module means Electron's complete OS-level userData
 * directory, including user content, Chromium state, and — on Windows and
 * Linux — application logs (macOS keeps logs in ~/Library/Logs instead).
 */

export function getNormalizedExecutablePath(): string {
  if (isLinux && process.env.APPIMAGE) {
    return path.join(path.dirname(process.env.APPIMAGE), 'cherry-studio.appimage')
  }
  if (isWin && isPortable) {
    return path.join(process.env.PORTABLE_EXECUTABLE_DIR || '', 'cherry-studio-portable.exe')
  }
  return app.getPath('exe')
}

export function canonicalizeUserDataPath(userDataPath: string): string {
  if (!path.isAbsolute(userDataPath)) {
    throw new Error(`userData path must be absolute: ${userDataPath}`)
  }
  return path.normalize(userDataPath)
}

/**
 * Resolve Electron's userData directory before the path registry is frozen.
 * Pending relocation is deliberately not executed here: after the source path
 * is resolved and its single-instance lock is acquired, the
 * `services/userDataRelocation` domain owns validation, copy/switch, commit,
 * progress UI, and relaunch (`runUserDataRelocation()` called from main.ts).
 * The `app.user_data_path` mapping read below is written by that domain's
 * commit step.
 *
 * Electron derives sessionData lazily from userData when no explicit
 * sessionData path was set. Keeping this setPath call before app.whenReady()
 * therefore carries Cookies, Local Storage, IndexedDB, and other Chromium
 * storage to the selected directory as well.
 */
export function resolveUserDataLocation(): void {
  if (!app.isPackaged) {
    const devPath = resolveDevUserDataPath()
    app.setPath('userData', devPath)
    logger.info('userData set with dev suffix', { devPath })
    return
  }

  const exe = getNormalizedExecutablePath()
  const resolved = bootConfigService.get('app.user_data_path')?.[exe]
  if (resolved && isUsableDataDir(resolved)) {
    app.setPath('userData', resolved)
    logger.info('userData set from BootConfig', { exe, resolved })
    return
  }

  if (isPortable) {
    const portableDir = process.env.PORTABLE_EXECUTABLE_DIR
    const portablePath = path.join(portableDir || app.getPath('exe'), 'data')
    app.setPath('userData', portablePath)
    logger.info('userData set for portable build', { portablePath })
    return
  }

  const brandedPath = path.join(app.getPath('appData'), PRODUCT_DIRNAME)
  app.setPath('userData', brandedPath)
  logger.info('userData set from branding', { brandedPath })
  warnOnUnadoptedLegacyDataDir(brandedPath)
}

/**
 * This fork deliberately starts with an empty profile rather than adopting an
 * upstream Cherry Studio one: the directory layouts are only coincidentally
 * compatible, and silently importing another app's data is worse than starting
 * clean. Log it so an operator can find the old directory instead of concluding
 * their data vanished.
 */
function warnOnUnadoptedLegacyDataDir(brandedPath: string): void {
  const legacyPath = path.join(app.getPath('appData'), LEGACY_UPSTREAM_DIRNAME)
  if (legacyPath === brandedPath || !isUsableDataDir(legacyPath)) return

  logger.warn('Legacy Cherry Studio data directory found and deliberately not adopted', {
    legacyPath,
    brandedPath
  })
}

/**
 * A usable data directory must be readable, writable, and searchable. This is
 * shared with v1-to-v2 migration path selection so both startup paths enforce
 * the same filesystem bar.
 */
export function isUsableDataDir(value: string): boolean {
  try {
    if (!fs.statSync(value).isDirectory()) return false
    fs.accessSync(value, fs.constants.R_OK | fs.constants.W_OK | fs.constants.X_OK)
    return true
  } catch {
    return false
  }
}

actual_packaged_validator:
const crypto = require('node:crypto')
const fs = require('node:fs')
const path = require('node:path')
const { spawnSync } = require('node:child_process')

const PROJECT_ROOT = path.resolve(__dirname, '..')
const UAR_VERSION_MARKER = '.uar-sidecar-version'
const LOCAL_PAYLOAD_MARKER = '.uar-local-payload.json'

function loadUarArtifactManifest() {
  const integration = require(path.join(PROJECT_ROOT, 'build', 'integration-artifacts.json'))
  const sidecar = integration.tools.find((tool) => tool.name === 'uar-sidecar')
  if (!sidecar) throw new Error('Integration artifact manifest is missing uar-sidecar')
  return { integration, sidecar }
}

function getUarPayloadInventory(platformKey) {
  const { sidecar } = loadUarArtifactManifest()
  const platformFamily = platformKey.split('-')[0]
  const exact = sidecar.packages?.[platformKey]
  const packages = exact
    ? [exact]
    : Object.entries(sidecar.packages || {})
        .filter(([candidate]) => candidate.startsWith(`${platformFamily}-`))
        .map(([, artifact]) => artifact)
  return [...new Set([...packages.flatMap((artifact) => artifact.binaries || []), UAR_VERSION_MARKER])].sort()
}

function getPackagedBinaryDirectory(resourcesDir, platformKey) {
  return path.join(resourcesDir, 'app.asar.unpacked', 'resources', 'binaries', platformKey)
}

function sha256(filename) {
  return crypto.createHash('sha256').update(fs.readFileSync(filename)).digest('hex')
}

function isSafeRelativePath(filename) {
  if (!filename || path.posix.isAbsolute(filename) || filename.includes('\\')) return false
  const normalized = path.posix.normalize(filename)
  return normalized === filename && normalized !== '..' && !normalized.startsWith('../')
}

function isPlatformSignedCode(filename, platformKey) {
  if (platformKey.startsWith('darwin-')) return filename === 'uar-sidecar' || filename.endsWith('.dylib')
  if (platformKey.startsWith('win32-')) return filename === 'uar-sidecar.exe'
  return false
}

function verifyPlatformSignature(filename, platformKey) {
  const result = platformKey.startsWith('darwin-')
    ? spawnSync('codesign', ['--verify', '--strict', '--verbose=2', filename], { encoding: 'utf8' })
    : spawnSync(
        'powershell.exe',
        [
          '-NoProfile',
          '-NonInteractive',
          '-Command',
          '(Get-AuthenticodeSignature -LiteralPath $env:UAR_SIGNED_FILE).Status'
        ],
        { env: { ...process.env, UAR_SIGNED_FILE: filename }, encoding: 'utf8', windowsHide: true }
      )
  const valid = platformKey.startsWith('darwin-')
    ? result.status === 0
    : result.status === 0 && result.stdout.trim() === 'Valid'
  if (!valid) {
    throw new Error(`Packaged UAR sidecar platform signature is invalid for ${platformKey}: ${path.basename(filename)}`)
  }
}

function loadLocalPayloadMarker(payloadDir, platformKey) {
  const pin = require(path.join(PROJECT_ROOT, 'build', 'local-uar-source.json'))
  const markerFile = path.join(payloadDir, LOCAL_PAYLOAD_MARKER)
  const marker = JSON.parse(fs.readFileSync(markerFile, 'utf8'))
  if (
    marker.schema !== 1 ||
    marker.name !== 'uar-sidecar' ||
    marker.version !== pin.version ||
    pin.platform !== platformKey ||
    marker.platform !== platformKey ||
    marker.source !== pin.revision ||
    !/^[a-f0-9]{64}$/.test(marker.archiveSha256) ||
    !Array.isArray(marker.files)
  ) {
    throw new Error(`Local UAR payload identity does not match its source pin for ${platformKey}`)
  }
  return marker
}

function verifyPackagedUarPayload(resourcesDir, platformKey, options = {}) {
  const { integration, sidecar } = loadUarArtifactManifest()
  const payloadDir = getPackagedBinaryDirectory(resourcesDir, platformKey)
  const localMarkerFile = path.join(payloadDir, LOCAL_PAYLOAD_MARKER)
  if (!options.localUar && fs.existsSync(localMarkerFile)) {
    throw new Error(`Local UAR payload cannot be used for a public release: ${platformKey}`)
  }
  const local = options.localUar ? loadLocalPayloadMarker(payloadDir, platformKey) : null
  const expected = local
    ? { binaries: [...local.files.map((entry) => entry.path), 'payload-manifest.json'] }
    : sidecar?.packages?.[platformKey]
  if (!expected) throw new Error(`Integration artifact manifest is missing uar-sidecar ${platformKey}`)

  const manifestFile = path.join(payloadDir, 'payload-manifest.json')
  const manifestStat = fs.statSync(manifestFile, { throwIfNoEntry: false })
  if (!manifestStat?.isFile() || manifestStat.size === 0) {
    throw new Error(`Packaged UAR sidecar manifest is missing or empty for ${platformKey}`)
  }

  const manifest = JSON.parse(fs.readFileSync(manifestFile, 'utf8'))
  if (
    manifest.schema !== 1 ||
    manifest.name !== 'uar-sidecar' ||
    manifest.version !== (local?.version ?? sidecar.version) ||
    manifest.platform !== platformKey ||
    manifest.source !== (local?.source ?? integration.sources.uar.revision) ||
    !Array.isArray(manifest.files)
  ) {
    throw new Error(`Packaged UAR sidecar manifest identity does not match the release pins for ${platformKey}`)
  }

  const declaredFiles = manifest.files.map((entry) => entry.path).sort()
  const expectedFiles = expected.binaries.filter((filename) => filename !== 'payload-manifest.json').sort()
  if (JSON.stringify(declaredFiles) !== JSON.stringify(expectedFiles)) {
    throw new Error(`Packaged UAR sidecar file inventory does not match the release pins for ${platformKey}`)
  }
  if (local) {
    const declared = [...manifest.files].sort((left, right) => left.path.localeCompare(right.path))
    const pinned = [...local.files].sort((left, right) => left.path.localeCompare(right.path))
    if (JSON.stringify(declared) !== JSON.stringify(pinned)) {
      throw new Error(`Packaged local UAR sidecar file hashes do not match their payload record for ${platformKey}`)
    }
  }

  for (const entry of manifest.files) {
    if (
      !isSafeRelativePath(entry.path) ||
      !Number.isSafeInteger(entry.size) ||
      entry.size <= 0 ||
      !/^[a-f0-9]{64}$/.test(entry.sha256)
    ) {
      throw new Error(`Invalid UAR sidecar manifest entry for ${platformKey}: ${entry.path || '<missing path>'}`)
    }
    const filename = path.join(payloadDir, ...entry.path.split('/'))
    const stat = fs.statSync(filename, { throwIfNoEntry: false })
    if (!stat?.isFile() || stat.size === 0) {
      throw new Error(`Packaged UAR sidecar file is missing or truncated for ${platformKey}: ${entry.path}`)
    }
    const payloadMatches = stat.size === entry.size && sha256(filename) === entry.sha256
    if (payloadMatches) continue
    if (options.allowPlatformSigning && isPlatformSignedCode(entry.path, platformKey)) {
      verifyPlatformSignature(filename, platformKey)
    } else {
      throw new Error(`Packaged UAR sidecar checksum mismatch for ${platformKey}: ${entry.path}`)
    }
  }

  const executable = path.join(payloadDir, platformKey.startsWith('win32-') ? 'uar-sidecar.exe' : 'uar-sidecar')
  const executableStat = fs.statSync(executable)
  if (!platformKey.startsWith('win32-') && (executableStat.mode & 0o111) === 0) {
    throw new Error(`Packaged UAR sidecar is not executable for ${platformKey}`)
  }

  return { executable, payloadDir }
}

function assertPackagedUarPayloadAbsent(resourcesDir, platformKey) {
  const payloadDir = getPackagedBinaryDirectory(resourcesDir, platformKey)
  const present = [...getUarPayloadInventory(platformKey), LOCAL_PAYLOAD_MARKER].filter((filename) =>
    fs.existsSync(path.join(payloadDir, ...filename.split('/')))
  )
  if (present.length > 0) {
    throw new Error(`Disabled-UAR package contains UAR payload for ${platformKey}: ${present.join(', ')}`)
  }
}

function probePackagedUarSidecar(executable, payloadDir, platformKey) {
  const result = spawnSync(executable, [], {
    cwd: payloadDir,
    input: 'invalid-launch-token\n',
    encoding: 'utf8',
    timeout: 30_000,
    windowsHide: true
  })
  if (result.error) throw new Error(`Packaged UAR sidecar could not launch for ${platformKey}: ${result.error.message}`)
  if (result.status !== 2 || !result.stderr.includes('UAR sidecar refused to start')) {
    throw new Error(
      `Packaged UAR sidecar launch probe failed for ${platformKey}: exit ${String(result.status)}, ` +
        `signal ${String(result.signal)}`
    )
  }
}

function verifyAndProbePackagedUarPayload(resourcesDir, platformKey, options) {
  const payload = verifyPackagedUarPayload(resourcesDir, platformKey, options)
  probePackagedUarSidecar(payload.executable, payload.payloadDir, platformKey)
  return payload
}

module.exports = {
  assertPackagedUarPayloadAbsent,
  getPackagedBinaryDirectory,
  getUarPayloadInventory,
  verifyAndProbePackagedUarPayload,
  verifyPackagedUarPayload
}

actual_archive_validator:
const crypto = require('node:crypto')
const { execFileSync } = require('node:child_process')
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')

const pin = require('../build/local-uar-source.json')
const MARKER = '.uar-local-payload.json'
const PACKAGE = `uar-sidecar-${pin.platform}`

function sha256(filename) {
  const digest = crypto.createHash('sha256')
  const file = fs.openSync(filename, 'r')
  const chunk = Buffer.allocUnsafe(1024 * 1024)
  try {
    let bytesRead
    while ((bytesRead = fs.readSync(file, chunk, 0, chunk.length, null)) > 0) {
      digest.update(chunk.subarray(0, bytesRead))
    }
  } finally {
    fs.closeSync(file)
  }
  return digest.digest('hex')
}

function isSafePath(filename) {
  if (typeof filename !== 'string' || !filename || filename.includes('\\') || path.posix.isAbsolute(filename))
    return false
  const normalized = path.posix.normalize(filename)
  return normalized === filename && normalized !== '..' && !normalized.startsWith('../')
}

function requireFile(filename) {
  const stat = fs.lstatSync(filename, { throwIfNoEntry: false })
  if (!stat?.isFile() || stat.size === 0) throw new Error(`Local UAR payload file is missing or empty: ${filename}`)
  return stat
}

function inspectLocalUarRecord() {
  if (process.env.CI) throw new Error('Local UAR payloads are forbidden in release CI')
  if (process.platform !== 'darwin' || process.arch !== 'arm64') {
    throw new Error('Local UAR payloads require a native Apple Silicon host')
  }
  const sourceDir = process.env.THE_BOSS_LOCAL_UAR_SOURCE_DIR?.trim()
  if (!sourceDir) throw new Error('Set THE_BOSS_LOCAL_UAR_SOURCE_DIR to the clean, pinned UAR checkout')
  const root = fs.realpathSync(sourceDir)
  const git = (...args) => execFileSync('git', ['-C', root, ...args], { encoding: 'utf8' }).trim()
  if (fs.realpathSync(git('rev-parse', '--show-toplevel')) !== root) {
    throw new Error('THE_BOSS_LOCAL_UAR_SOURCE_DIR must name the UAR checkout root')
  }
  const source = git('rev-parse', 'HEAD')
  if (source !== pin.revision) throw new Error(`Local UAR source ${source} does not match ${pin.revision}`)
  if (git('status', '--porcelain', '--untracked-files=all', '--', '.', ':(exclude)dist/boss-sidecar')) {
    throw new Error('Local UAR source checkout has uncommitted or untracked changes')
  }

  const output = path.join(root, 'dist', 'boss-sidecar')
  const recordFile = path.join(output, `${PACKAGE}.json`)
  const record = JSON.parse(fs.readFileSync(recordFile, 'utf8'))
  if (
    record.name !== 'uar-sidecar' ||
    record.version !== pin.version ||
    record.platform !== pin.platform ||
    record.source !== pin.revision ||
    record.asset !== `${PACKAGE}.tar.gz` ||
    record.archive !== 'tar.gz' ||
    !Array.isArray(record.binaries) ||
    record.binaries.length === 0 ||
    !/^[a-f0-9]{64}$/.test(record.sha256)
  ) {
    throw new Error('Local UAR payload record does not match the pinned source and platform')
  }
  const archive = path.join(output, record.asset)
  requireFile(archive)
  if (sha256(archive) !== record.sha256) throw new Error('Local UAR archive checksum does not match its record')
  return { archive, record }
}

function loadLocalUarPayload() {
  const { archive, record } = inspectLocalUarRecord()
  const packageRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'the-boss-local-uar-'))
  try {
    const archiveEntries = execFileSync('tar', ['tzf', archive], { encoding: 'utf8' }).trim().split('\n')
    if (
      archiveEntries.some(
        (name) =>
          name !== `${PACKAGE}/` && (!name.startsWith(`${PACKAGE}/`) || !isSafePath(name.slice(PACKAGE.length + 1)))
      )
    ) {
      throw new Error('Local UAR archive contains an unexpected path')
    }
    execFileSync('tar', ['xzf', archive, '-C', packageRoot, '--strip-components=1'])
    const manifest = JSON.parse(fs.readFileSync(path.join(packageRoot, 'payload-manifest.json'), 'utf8'))
    if (
      manifest.schema !== 1 ||
      manifest.name !== 'uar-sidecar' ||
      manifest.version !== pin.version ||
      manifest.platform !== pin.platform ||
      manifest.source !== pin.revision ||
      !Array.isArray(manifest.files) ||
      !Array.isArray(record.binaries)
    ) {
      throw new Error('Local UAR file manifest does not match the pinned source and platform')
    }
    const files = manifest.files
    const names = files.map((entry) => entry.path)
    if (
      new Set(names).size !== names.length ||
      !names.includes('uar-sidecar') ||
      !names.includes('uar-models/config.json')
    ) {
      throw new Error('Local UAR file manifest has missing or duplicate files')
    }
    if (JSON.stringify([...names, 'payload-manifest.json'].sort()) !== JSON.stringify([...record.binaries].sort())) {
      throw new Error('Local UAR file manifest does not match its archive record')
    }
    for (const entry of files) {
      if (
        !isSafePath(entry.path) ||
        !Number.isSafeInteger(entry.size) ||
        entry.size <= 0 ||
        !/^[a-f0-9]{64}$/.test(entry.sha256)
      ) {
        throw new Error(`Invalid local UAR file record: ${entry.path || '<missing path>'}`)
      }
      const filename = path.join(packageRoot, ...entry.path.split('/'))
      const stat = requireFile(filename)
      if (stat.size !== entry.size || sha256(filename) !== entry.sha256) {
        throw new Error(`Local UAR file checksum does not match its manifest: ${entry.path}`)
      }
    }

    return {
      packageRoot,
      marker: {
        schema: 1,
        name: 'uar-sidecar',
        version: pin.version,
        platform: pin.platform,
        source: pin.revision,
        archiveSha256: record.sha256,
        files
      },
      cleanup: () => fs.rmSync(packageRoot, { recursive: true, force: true })
    }
  } catch (error) {
    fs.rmSync(packageRoot, { recursive: true, force: true })
    throw error
  }
}

function stageLocalUarPayload(binaryDirectory) {
  const { packageRoot, marker, cleanup } = loadLocalUarPayload()
  try {
    const priorMarker = path.join(binaryDirectory, MARKER)
    const priorFiles = fs.existsSync(priorMarker) ? JSON.parse(fs.readFileSync(priorMarker, 'utf8')).files : []
    const canonical = require('../build/integration-artifacts.json').tools.find((tool) => tool.name === 'uar-sidecar')
    const owned = [
      ...(canonical?.packages?.[pin.platform]?.binaries || []),
      ...(priorFiles || []).map((entry) => entry.path)
    ]
    for (const filename of owned) {
      if (!isSafePath(filename)) throw new Error(`Invalid prior UAR payload path: ${filename}`)
      fs.rmSync(path.join(binaryDirectory, ...filename.split('/')), { force: true })
    }
    fs.rmSync(path.join(binaryDirectory, 'uar-models'), { recursive: true, force: true })
    for (const entry of marker.files) {
      const destination = path.join(binaryDirectory, ...entry.path.split('/'))
      fs.mkdirSync(path.dirname(destination), { recursive: true })
      fs.copyFileSync(path.join(packageRoot, ...entry.path.split('/')), destination)
    }
    const manifest = JSON.parse(fs.readFileSync(path.join(packageRoot, 'payload-manifest.json'), 'utf8'))
    fs.writeFileSync(
      path.join(binaryDirectory, 'payload-manifest.json'),
      `${JSON.stringify({ ...manifest, archiveSha256: marker.archiveSha256 }, null, 2)}\n`
    )
    fs.chmodSync(path.join(binaryDirectory, 'uar-sidecar'), 0o755)
    fs.writeFileSync(path.join(binaryDirectory, '.uar-sidecar-version'), pin.version)
    fs.writeFileSync(priorMarker, `${JSON.stringify(marker, null, 2)}\n`)
  } finally {
    cleanup()
  }
}

function assertNoLocalUarPayload(binaryDirectory) {
  if (fs.existsSync(path.join(binaryDirectory, MARKER))) {
    throw new Error('Local UAR payload is present; public or non-UAR packaging requires a clean binary directory')
  }
}

module.exports = { MARKER, assertNoLocalUarPayload, inspectLocalUarRecord, loadLocalUarPayload, stageLocalUarPayload }

actual_installer_validator:
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')
const { execFileSync } = require('node:child_process')

const { RETAINED_NATIVE_TOOLS, resolveReleaseProfile } = require('./release-profile.cjs')
const {
  assertPackagedUarPayloadAbsent,
  getPackagedBinaryDirectory,
  verifyAndProbePackagedUarPayload
} = require('./uar-payload-integrity.cjs')

const root = path.resolve(__dirname, '..')
const platformKey = process.argv[2]
const nativePlatformKey = `${process.platform}-${process.arch}`
const version = require('../package.json').version
const profile = resolveReleaseProfile()
const requireNotarization = process.env.HAS_NOTARIZATION === 'true'

if (!profile.supportedPlatforms.includes(platformKey)) {
  throw new Error(`usage: node scripts/validate-release-package.cjs <${profile.supportedPlatforms.join('|')}>`)
}
if (platformKey !== nativePlatformKey) {
  throw new Error(`Release package ${platformKey} must be validated on its native ${nativePlatformKey} runner`)
}

function findArtifact(suffix) {
  const matches = fs
    .readdirSync(path.join(root, 'dist'))
    .filter((name) => name.includes(version) && name.toLowerCase().endsWith(suffix.toLowerCase()))
  if (matches.length !== 1) throw new Error(`Expected one ${platformKey} ${suffix} artifact, found ${matches.length}`)
  return path.join(root, 'dist', matches[0])
}

function verifyPackagedApplication(resourcesDir) {
  const appAsar = path.join(resourcesDir, 'app.asar')
  const appAsarStat = fs.statSync(appAsar, { throwIfNoEntry: false })
  if (!appAsarStat?.isFile() || appAsarStat.size === 0) {
    throw new Error('Packaged application is missing its app.asar payload')
  }

  const integration = require('../build/integration-artifacts.json')
  const binaryDirectory = getPackagedBinaryDirectory(resourcesDir, platformKey)
  for (const name of RETAINED_NATIVE_TOOLS) {
    const tool = integration.tools.find((candidate) => candidate.name === name)
    const artifact = tool?.packages?.[platformKey]
    if (!tool || !artifact) throw new Error(`Release manifest is missing ${name} for ${platformKey}`)
    for (const filename of artifact.binaries) {
      const packaged = path.join(binaryDirectory, ...filename.split('/'))
      const stat = fs.statSync(packaged, { throwIfNoEntry: false })
      if (!stat?.isFile() || stat.size === 0) throw new Error(`Packaged ${name} payload is missing: ${filename}`)
    }
    const marker = path.join(binaryDirectory, `.${name}-version`)
    if (fs.readFileSync(marker, 'utf8').trim() !== tool.version) {
      throw new Error(`Packaged ${name} version marker does not match ${tool.version}`)
    }
  }

  if (profile.uarEnabled) {
    verifyAndProbePackagedUarPayload(resourcesDir, platformKey, {
      allowPlatformSigning: true,
      localUar: profile.localUar
    })
  } else assertPackagedUarPayloadAbsent(resourcesDir, platformKey)
}

function verifyApplicationBundle(app) {
  const info = path.join(app, 'Contents', 'Info.plist')
  execFileSync('plutil', ['-lint', info], { stdio: 'inherit' })
  const executableName = execFileSync('plutil', ['-extract', 'CFBundleExecutable', 'raw', '-o', '-', info], {
    encoding: 'utf8'
  }).trim()
  const executable = path.join(app, 'Contents', 'MacOS', executableName)
  const executableStat = fs.statSync(executable, { throwIfNoEntry: false })
  if (!executableStat?.isFile() || executableStat.size === 0 || (executableStat.mode & 0o111) === 0) {
    throw new Error('Mounted DMG contains no usable application executable')
  }
  const sealedResources = path.join(app, 'Contents', '_CodeSignature', 'CodeResources')
  const sealedResourcesStat = fs.statSync(sealedResources, { throwIfNoEntry: false })
  if (!sealedResourcesStat?.isFile() || sealedResourcesStat.size === 0) {
    throw new Error('Mounted DMG application is missing its sealed code resources')
  }
  execFileSync('codesign', ['--verify', '--deep', '--strict', '--verbose=4', app], { stdio: 'inherit' })
  if (requireNotarization) {
    execFileSync('xcrun', ['stapler', 'validate', app], { stdio: 'inherit', timeout: 60_000 })
    execFileSync('spctl', ['--assess', '--type', 'execute', '--verbose=4', app], { stdio: 'inherit' })
  } else {
    process.stdout.write('Notarization validation skipped because HAS_NOTARIZATION is not true\n')
  }
  verifyPackagedApplication(path.join(app, 'Contents', 'Resources'))
}

function detachMountedImage(mount) {
  for (let attempt = 0; attempt < 5; attempt += 1) {
    try {
      execFileSync('hdiutil', ['detach', mount], { stdio: 'pipe', timeout: 60_000 })
      return
    } catch {
      if (attempt < 4) Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 1_000)
    }
  }
  execFileSync('hdiutil', ['detach', '-force', mount], { stdio: 'inherit', timeout: 60_000 })
}

function validateDmg() {
  const artifact = findArtifact(`-${process.arch}.dmg`)
  execFileSync('hdiutil', ['verify', artifact], { stdio: 'inherit', timeout: 120_000 })
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'the-boss-dmg-'))
  const mount = path.join(temporary, 'mounted')
  fs.mkdirSync(mount)
  let mounted = false
  try {
    execFileSync('hdiutil', ['attach', '-nobrowse', '-readonly', '-mountpoint', mount, artifact], {
      stdio: 'inherit',
      timeout: 120_000
    })
    mounted = true
    const apps = fs
      .readdirSync(mount)
      .filter((name) => name.endsWith('.app'))
      .map((name) => path.join(mount, name))
      .filter((filename) => fs.statSync(filename).isDirectory())
    if (apps.length !== 1) throw new Error(`Expected one application bundle in the DMG, found ${apps.length}`)
    verifyApplicationBundle(apps[0])
  } finally {
    try {
      if (mounted) detachMountedImage(mount)
    } finally {
      fs.rmSync(temporary, { recursive: true, force: true })
    }
  }
}

function validateWindowsInstaller() {
  const artifact = findArtifact(`-${process.arch}-setup.exe`)
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'the-boss-installer-'))
  const installation = path.join(temporary, 'The Boss')
  try {
    execFileSync(artifact, ['/S', `/D=${installation}`], { stdio: 'inherit', timeout: 300_000, windowsHide: true })
    const executable = path.join(installation, 'The Boss.exe')
    const executableStat = fs.statSync(executable, { throwIfNoEntry: false })
    if (!executableStat?.isFile() || executableStat.size === 0) {
      throw new Error('NSIS installer contains no usable application executable')
    }
    verifyPackagedApplication(path.join(installation, 'resources'))
  } finally {
    fs.rmSync(temporary, { recursive: true, force: true })
  }
}

if (platformKey.startsWith('darwin-')) validateDmg()
else validateWindowsInstaller()

process.stdout.write(`Validated ${platformKey} installer and ${profile.id} application image\n`)

